      for (let a = 0; a < 3; a++) { const q = h3[3 * j + a] - 3 * h2[3 * j + a] + 3 * h1[3 * j + a] - h0[3 * j + a]; jx += q * q; const st = h3[3 * j + a] - h2[3 * j + a]; sx += st * st; }
