    let bd = Infinity, bj = 0; for (let j = 0; j < m; j++) { const d = (P[3 * j] - p.pos[0]) ** 2 + (P[3 * j + 1] - p.pos[1]) ** 2 + (P[3 * j + 2] - p.pos[2]) ** 2; if (d < bd) { bd = d; bj = j; } }
