function mean(a) { let s = 0; for (const x of a) s += x; return a.length ? s / a.length : 0; }
function median(sorted) { const n = sorted.length; if (!n) return 0; return n % 2 ? sorted[(n - 1) / 2] : 0.5 * (sorted[n / 2 - 1] + sorted[n / 2]); }
